"""Negative spikes inside parentheses that spell out or abbreviate a term.

Component: layers.15.mlp.down_proj:5385. Its input is almost entirely one MLP hidden unit of
layer 15, so its activation is that unit's signed value. Most positions sit near zero. The
large negative values come inside parentheses, where the text names or abbreviates the term
just before it:

- the first token inside "(" when it is an acronym (capitals, up to six letters) in running
  prose, as in "Upper Atmosphere Research Satellite (UARS)" or "Member (MP)". Strongest
  (about -7) when the acronym's letters are the initials of the words just before the "(";
  about -4 otherwise. Acronyms in code or maths are only slightly negative (about -0.8).
- the first token inside any other "(": capitalised about -0.9, lowercase about -0.7;
- acronym tokens later inside a parenthesis (about -0.6), and word fragments continuing a
  split word inside one ("(head[way])", about -0.4);
- other tokens inside a parenthesis, a little below zero;
- a few tokens after a naming cue ("called", "i.e.", "aka", "known as"): about -0.45.

Everything else sits at a small negative baseline. Parentheses that hold a date range or an
"or" alternative average near zero (a few come out clearly positive), and the spread of the
activation outside parentheses has no simple cause that this program can read.

The values are the mean activations measured on training text for each category, so the
program is a readable table of those categories rather than a fit of the unit's internals.
"""

import re

READS = ()

STOP_WORDS = {"and", "of", "the", "for", "in", "on", "a", "an", "to", "with", "by", "de", "la",
              "en", "et", "des", "du"}
NAMING_CUES = ("called", "i.e.", "e.g.", "aka", "known as", "abbreviated", "referred to as",
               "short for")
CODE_OR_MATH = re.compile(r"[=;{}\[\]$\\_<>]|\(\(|\)\)|\.\w+\(")

BASE = -0.05
ACRONYM_INITIALS = -6.7  # prose acronym whose letters are the initials of the words before it
ACRONYM_PROSE = -3.7  # any other prose acronym opening a parenthesis
ACRONYM_CODE = -0.8  # acronym opening a parenthesis in code or maths
CAPITAL_OPEN = -0.9  # capitalised word opening a parenthesis
LOWER_OPEN = -0.7  # lowercase word opening a parenthesis
ACRONYM_LATER = -0.6  # acronym later inside a parenthesis
FRAGMENT = -0.4  # word fragment continuing a split word inside a parenthesis
INSIDE = -0.12  # any other token inside a parenthesis
CUE = -0.45  # a few tokens after a naming cue


def is_acronym(word):
    letters = word.replace("-", "")
    return 1 <= len(letters) <= 6 and letters.isupper()


def initials_match(acronym, before):
    letters = acronym.replace("-", "").lower()
    words = [w for w in re.findall(r"[A-Za-z][A-Za-z-]*", before) if w.lower() not in STOP_WORDS]
    if len(letters) < 2 or len(words) < len(letters):
        return False
    return "".join(w[0] for w in words[-len(letters):]).lower() == letters


def opening_value(word, token, before):
    if is_acronym(word):
        if CODE_OR_MATH.search(before[-40:]) or not re.search(r"[A-Za-z]\s*$", before):
            return ACRONYM_CODE
        if initials_match(word, before):
            return ACRONYM_INITIALS
        return ACRONYM_PROSE
    if word[:1].isupper():
        return CAPITAL_OPEN
    if word[:1].isalpha():
        return LOWER_OPEN
    return INSIDE


def fresh(doc):
    return {"doc": doc, "depth": 0, "inside": "", "before": "", "tail": "", "recent": [],
            "prev": ""}


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    word = token.strip()
    if carry is None or carry["doc"] != prefix.document_ids[t]:
        carry = fresh(prefix.document_ids[t])
    if carry["depth"] > 0:
        if carry["inside"].strip() == "":  # the first token inside the parenthesis
            value = opening_value(word, token, carry["before"])
        elif is_acronym(word):
            value = ACRONYM_LATER
        elif not token[:1].isspace() and word.isalpha() and carry["prev"].strip().isalpha():
            value = FRAGMENT
        else:
            value = INSIDE
    elif any(cue in " ".join(carry["recent"]) for cue in NAMING_CUES):
        value = CUE
    else:
        value = BASE
    # update the state with this token's characters
    for ch in token:
        if ch == "(":
            carry["depth"] += 1
            carry["inside"] = ""
            carry["before"] = carry["tail"]
        elif ch == ")":
            carry["depth"] = max(carry["depth"] - 1, 0)
            carry["inside"] = ""
        elif carry["depth"] > 0:
            carry["inside"] += ch
    carry["tail"] = (carry["tail"] + token)[-160:]
    carry["recent"] = (carry["recent"] + [token])[-6:]
    carry["prev"] = token
    return carry, float(value)

"""Layer 15 MLP hidden unit 5386 (this component reads almost only that unit).

Plain-language reading: a concession detector. It is strongly positive on the word that opens
a concessive clause ("Although", "Though", "Despite", "albeit", "虽然"), most of all at the start
of a sentence, and on "not" inside such a clause ("while not", "although not"). It is weaker on
"not" after a hedge ("might not", "maybe not"), on "While" opening a clause, and on n't
contractions. It is negative on C-family and Java declaration words ("void", indented "this",
"public", "boolean"). Everywhere else it predicts 0. It explains only a few percent of the
variance: most of it is context noise that a word-level rule cannot capture.
"""

READS = ()

CONCESSIVE = {"although", "though", "despite", "albeit", "虽然", "雖然", "尽管", "儘管", "即使"}
SENTENCE_START = {"", ".", "。", "!", "?", "\n", '"', "“", "and", "even", "but"}
HEDGE_BEFORE_NOT = {"might", "may", "maybe", "perhaps", "could"}
BE_BEFORE_NT = {"was", "were", "is", "are", "wasn", "weren", "isn", "aren"}
CODE_VALUE = {"void": -2.5, "\tthis": -2.2, "public": -1.0, "\tpublic": -1.0, "boolean": -1.3, "static": -0.6}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    recent = [s.strip().lower() for s in prefix.token_strings[-4:-1]]
    starts_clause = before in SENTENCE_START
    if word in CONCESSIVE:
        value = 5.0 if starts_clause else 2.5
    elif word in ("while", "whilst"):
        value = 4.0 if starts_clause else 0.7
    elif word in ("not", "never"):
        if any(w in CONCESSIVE or w in ("while", "whilst") for w in recent):
            value = 5.0
        elif before in HEDGE_BEFORE_NOT:
            value = 1.0
        else:
            value = 0.25
    elif word in ("'t", "’t"):
        value = 1.2 if before in BE_BEFORE_NT else 0.4
    elif word in ("might", "may", "maybe", "perhaps", "hardly"):
        value = 0.3
    else:
        value = CODE_VALUE.get(token, CODE_VALUE.get(raw, 0.0))
    return carry, float(value)

"""Layer 15 MLP hidden unit 5390 (this component is that unit's write into the residual stream).

The unit is a SwiGLU unit: its value is silu(gate) * up, mostly near zero with rare large spikes
of either sign. Its spikes are not predictable from what the token is alone (a per-token table
explains under 2% of its variance), so this program predicts only the tendencies that show up
in averages over many tokens, from the current token and the one before it:

- it leans positive on words that open a qualifying clause or an example: relative pronouns
  (which, who, where) and "including", "e.g.";
- it leans positive right after an opening parenthesis;
- it leans negative on list coordinators (",", "and", "or") and right after "or";
- otherwise it sits at the overall mean, about -0.03.

Each rule is a conditional mean measured on about 20k training rows. Together they explain only
about 0.2% of the variance, so this is a description of the sign of the typical tendency,
not an accurate model of the unit.
"""

READS = ()

INTRODUCERS = {"which", "who", "whom", "whose", "where", "including", "e.g", ".g"}
OPENERS = {"(", "（"}
COORDINATORS = {",", "and", "or"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if cur in INTRODUCERS:
        value = 0.20
    elif prev in OPENERS:
        value = 0.13
    elif cur in COORDINATORS:
        value = -0.11
    elif prev == "or":
        value = -0.08
    else:
        value = -0.03
    return carry, value

"""Layer 15 MLP down_proj component 5393: a weak word-versus-punctuation rule.

The component's activation is mostly a diffuse, context-dependent signal (mean about 0.03,
std about 0.29). Its value is slightly higher on words and digits, near zero on whitespace
and punctuation, and near zero at the first token of each document. This program predicts
those per-class averages. It explains almost none of the variance (about 0.2%), so it is a
weak description, not a faithful one.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()


def token_class(text: str) -> str:
    s = text.strip()
    if s == "":
        return "space"
    if s.isascii() and s.isalpha():
        return "word"
    if any(c.isdigit() for c in s):
        return "digit"
    if all(not c.isalnum() for c in s):
        return "punct"
    return "other"


MEAN_BY_CLASS = {"word": 0.037, "digit": 0.039, "other": 0.026, "punct": 0.005, "space": 0.0}


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return carry, 0.003
    return carry, MEAN_BY_CLASS[token_class(prefix.token_strings[t])]

"""Layer 15 MLP down-projection, component 5396.

What it does, in plain terms: this component is mostly quiet, and its large
values come from whitespace inside code and a few gendered words.

- Strongly negative on an escaped tab ("\\t" written out as two characters, as
  in a quoted line of source code) that follows a newline or another escaped
  tab, i.e. indentation inside code strings. Mildly negative on an escaped tab
  elsewhere.
- Mildly negative on runs of real indentation (spaces or tabs) that start a line,
  and on non-breaking-space indentation runs.
- Mildly positive on male-referring words (he, his, him, men, guy, husband, son,
  boy, ...), and on "is"/"are" right after a question word (What, Which, who,
  following, one).
- Zero everywhere else.

The rules are fixed values chosen from the data, not a fit to the model's
weights. They capture only a small part of the variance: most of the
component's activation depends on longer context that a token rule cannot see.
"""

READS: tuple = ()

MALE = {" he", " his", " him", " himself", " men", " man", " guy", " guys", " husband",
        " boy", " sons", " son", " He", " His", " Him", " Men", " Guy", " Boy"}
QUESTION_WORDS = {"What", "Which", "who", "following", "one"}


def is_blank(s):
    return len(s) > 0 and all(ch in " \t\xa0" for ch in s)


def is_newline(s):
    return s.endswith("\n") or s == "n" or s.endswith("\\n")


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    prev = s[-2] if len(s) > 1 else ""
    if cur == "\\t":
        return None, (-7.0 if prev in ("n", "\\t") else -1.5)
    if is_blank(cur):
        if "\xa0" in cur:
            return None, -0.6
        if is_newline(prev):
            return None, -0.4
        return None, 0.0
    if cur in MALE:
        return None, 0.85
    if cur in (" is", " are") and prev in QUESTION_WORDS:
        return None, 1.5
    return None, 0.0

"""Layer 15, MLP hidden unit 5401 (the component's main piece), read as a word detector.

What it responds to, in plain terms: the unit is weakly and noisily active where the text
states a need or a necessity ("need", "needed", "requires", "must", "want", "necessary",
"important") and where it draws a consequence ("therefore", "thus", "so", "hence",
"why"). It is also mildly positive on a comma that closes an opening clause such as
"if ...," or "because ...,", where a main clause should follow.

The program predicts those levels from the current token and is 0 everywhere else, and
resets at each document start. It explains only a small part of the variance: most of the
unit's activity is not tied to any word or sentence feature this program can name.
"""

READS = ()

# Typical activation on words of need or necessity, and on consequence words.
NEED = {"need": 1.8, "needs": 1.0, "needed": 1.4, "requires": 1.0, "require": 0.5,
        "necessary": 0.4, "essential": 0.4, "crucial": 0.3, "important": 0.4,
        "must": 0.5, "want": 0.9, "wanted": 0.7}
CONSEQUENCE = {"therefore": 1.2, "thus": 0.6, "so": 0.5, "hence": 0.8,
               "consequently": 0.8, "why": 0.9}
# Words that open a clause which a comma then closes.
OPENERS = {"if", "when", "because", "since", "as", "given", "although", "though",
           "once", "after", "while", "unless", "until", "before"}
SENTENCE_END = {".", "!", "?"}


def step(carry, prefix, upstream):
    # carry: (inside an opening clause, document id of the last token) or None.
    doc = prefix.document_ids[-1]
    in_clause = carry[0] if carry is not None and carry[1] == doc else False
    word = prefix.token_strings[-1].strip().lower()
    if word in NEED:
        value = NEED[word]
    elif word in CONSEQUENCE:
        value = CONSEQUENCE[word]
    elif word == "," and in_clause:
        value = 0.3
    else:
        value = 0.0
    if word in SENTENCE_END or "\n" in prefix.token_strings[-1]:
        in_clause = False
    if word in OPENERS:
        in_clause = True
    return (in_clause, doc), float(value)

"""Counting vs. size: a word-level sketch of down_proj component 5405 in layer 15.

The component reads MLP unit 5405 of layer 15 (its activation is that unit's hidden value,
scaled). It is negative when the text is about counting things and positive when it is
about size, degree or number.
Strongly negative values sit on quantity words ("many", "number", "fewer", "total") and on
the countable things being counted ("points", "digits", "tests", "nodes"), hardest right
after a quantity word ("how many [characters]", "the number [of]"). Strongly positive values
sit on size, degree and change words ("high", "low", "large", "small", "increase", "reduce")
and on number words ("six" ... "thousand"). Most other tokens sit near zero.

This program looks only at the current word and the two words before it (within its
document), and predicts one value per class. It captures a small share of the variance:
the activation is spread over thousands of words and contexts, and a 100-word table
does about as well. Plural-noun detection uses inflect's singular forms.
"""

import inflect

READS = ()

ENGINE = inflect.engine()

COUNT_WORDS = {  # quantity words: how many / how much
    "many", "much", "few", "fewer", "lot", "lots", "number", "numbers", "amount", "total",
    "count", "several", "multiple", "numerous", "plenty",
}
AMOUNT_VERBS = {  # verbs that take a count or amount as object
    "has", "have", "had", "scored", "sold", "received", "needed", "remaining", "available",
    "contains", "played", "produced", "added", "required", "used", "won", "earned", "spent",
}
SIZE_WORDS = {  # size, degree and change
    "high", "higher", "highest", "low", "lower", "lowest", "large", "larger", "largest",
    "big", "bigger", "biggest", "small", "smaller", "smallest", "short", "shorter", "long",
    "longer", "increase", "increased", "decrease", "decreased", "reduce", "reduced",
    "maximum", "minimum", "average", "median", "greater", "huge", "tiny", "faster", "wide",
}
NUMBER_WORDS = {  # from six up; one to four read near zero
    "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "twenty", "thirty",
    "hundred", "thousand", "million",
}
EXCEPTIONS = {"this", "is", "was", "has", "its", "his", "as", "us", "does", "less", "class",
              "process", "success", "access", "news", "series", "species", "years", "always"}


def is_plural_noun(word):
    """A plural English noun, by its ending and inflect's singular form."""
    if not word.isalpha() or len(word) < 4 or not word.endswith("s") or word.endswith("ss"):
        return False
    return word not in EXCEPTIONS and bool(ENGINE.singular_noun(word))


def step(carry, prefix, upstream):
    # the current word and the two before it, if they are in the same document
    words = ["", "", ""]
    for back in range(min(3, len(prefix.token_strings))):
        if prefix.document_ids[-1 - back] == prefix.document_ids[-1]:
            words[-1 - back] = prefix.token_strings[-1 - back].strip().lower()
    word, before, before2 = words[-1], words[-2], words[-3]
    if word == "of" and before in COUNT_WORDS:
        value = -1.8  # "the number [of]", "amount [of]"
    elif word in COUNT_WORDS:
        value = -1.0
    elif word in AMOUNT_VERBS:
        value = -0.5
    elif word in SIZE_WORDS or word in NUMBER_WORDS:
        value = 0.7
    elif is_plural_noun(word):
        if before == "of" and before2 in COUNT_WORDS:
            value = -3.5  # the counted things: "number of [digits]"
        elif before in COUNT_WORDS:
            value = -1.0  # "many [points]"
        else:
            value = -0.4
    elif before == "of" and before2 in COUNT_WORDS:
        value = -1.0
    else:
        value = 0.0
    return carry, value

"""Fires on punctuation that opens a value: a colon after a label, or an opening quote,
and more weakly on assignment and arrow-like operators that introduce what follows."""

READS = ()

OPEN_QUOTES = {' "', ' “', " '", ' ‘', '("', "('", '「', ' \\"', '(\\"'}
OPERATORS = {' =', ' ->', ' `', '::', '":', ' :', '):', '=', '))', ' {'}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ''
    if tok.rstrip('\n') in (':', '：'):
        if prev[-1:].isdigit():
            return carry, 0.0
        return carry, 3.0 if prev.strip()[-1:].isalpha() else 2.0
    if tok in OPEN_QUOTES:
        return carry, 2.3
    if tok in OPERATORS:
        return carry, 1.0
    return carry, 0.0

"""Opening-quotation detector for layers.15.mlp.down_proj component 5416.

What the component does, in plain terms: it switches on at the mark that opens a
quotation, most strongly when the quotation starts a new sentence or paragraph and
is a full statement (after a sentence end, a line break, or a verb of saying such as
"says", "states", "called", "that"). It is weaker when the quote marks a single term
inside a phrase ("the term “gastronomy”"), and near zero for quote marks in code or
JSON (after "=", ":", "," or "{"). It also fires a little on the colon that introduces
speech and on the first word inside a quotation.

The program predicts the activation from the newest token and the text before it:
  - curly opening quotes “ „ « 「 ‘ (and `` ), or a straight " merged with a word
    ("We): 9 at a sentence start, 4 mid-sentence;
  - a straight opening quote with a leading space: 3 at a sentence start, 1.5 mid-sentence,
    0 in code;
  - a colon: 0.85;
  - the token right after an opening quote: 0.5;
  - everything else: 0.
It keeps no state beyond the text it reads, so it is exact about its own rule but
misses the large diffuse spread of small values across ordinary tokens.
"""

READS = ()

OPENERS = ("“", "„", "«", "「", "‘", "``")
SENTENCE_END = (".", "!", "?", ":", "\n", "：")
SPEECH_WORDS = {
    "says", "said", "states", "stated", "called", "that", "wrote", "writes",
    "explains", "explained", "notes", "noted", "claims", "claimed", "adds",
    "added", "told", "reads", "according", "argued",
}
CODE_BEFORE = ("=", "+", "<", ">", "(", "[", "{", '":', '",', "},", "==")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    body = tok.lstrip(" ")
    before = prefix.text_prefixes[-2].rstrip() if len(prefix.text_prefixes) > 1 else ""
    words = before.split()
    at_sentence_start = (
        not before
        or before.endswith(SENTENCE_END)
        or (bool(words) and words[-1] in SPEECH_WORDS)
    )
    if tok.strip() == ":":
        return carry, 0.85
    if body.startswith(OPENERS) or (body.startswith('"') and body[1:2].isalpha()):
        return carry, (9.0 if at_sentence_start else 4.0)
    if body.startswith('"') and tok.startswith(" "):
        if before.endswith(CODE_BEFORE):
            return carry, 0.0
        return carry, (3.0 if at_sentence_start else 1.5)
    if len(prefix.token_strings) > 1 and prefix.token_strings[-2].lstrip(" ").startswith(OPENERS):
        return carry, 0.5
    return carry, 0.0

"""Layer 15 MLP hidden unit 5425, read as the component's activation.

The component reads (almost exactly) this one hidden unit of the layer-15 MLP, so its
activation is that unit's value times a constant. The unit is mostly quiet. Its clearest
behaviour: it goes strongly negative on an opening bracket that starts a term inside a
squared or distance expression ("sqrt( (", "(x - y)^2", "((a+b)^2"), and it is mildly
positive on aggregation and calculus words ("sum", "average", "mean", "integral", "dx").
It is zero at the first token of a document, and its squared-expression context does not
reach across a document boundary. The program writes those rules down as numbers.
"""

READS = ()

OPEN_NEG = {" (-", "(-", "*(-"}
OPEN_DOUBLE = {" ((", "((", " [(", "{("}
OPEN = {" (", " ["}
MINUS = {"-", " -", "−", " −"}
AGG = {"sum", " sum", "Sum", "average", " average", "aver", "mean", " mean", ".mean",
       "integr", " integr", " integral", "int", "∫", "dx", " dx", "partial", "∂",
       "cos", " cos", "sin", " sin", "dt", " dr"}
SQUARE_WORDS = {"sqrt", " sqrt", "distance", " distance", "squared", " squared",
                "^", "²", "^2", "magnitude", " magnitude", "length", " length", "|"}
WINDOW = 20


def step(carry, prefix, upstream):
    # The current document's last WINDOW tokens.
    docs = prefix.document_ids
    start = len(docs) - 1
    while start > 0 and docs[start - 1] == docs[-1] and start > len(docs) - WINDOW:
        start -= 1
    tokens = prefix.token_strings[start:]
    if len(tokens) < 2:
        return carry, 0.0
    tok = tokens[-1]
    squared = any(t in SQUARE_WORDS for t in tokens[:-1])
    if tok in OPEN_NEG:
        value = -6.0 if squared else -3.0
    elif tok in OPEN_DOUBLE:
        value = -12.0 if squared else -1.0
    elif tok in OPEN:
        value = -3.0 if squared else -0.2
    elif tok in MINUS:
        value = -1.0 if squared else -0.3
    elif tok in AGG:
        value = 2.0 if squared else 1.0
    else:
        value = 0.0
    return carry, float(value)

"""Component 5426 of layers.15.mlp.down_proj: a "a verb or member name comes next" detector.

The component is positive on the word just before the text expects a bare verb, a
predicate, or a method name, and near zero elsewhere. Its activation is roughly a fixed
value per word class, so the program looks up the newest token's class:

- "fp": first- and second-person pronouns as subjects, I / we / you (and me, us):
  "I can", "we will", "you should";
- "modal": modal verbs, will, would, should, can, could, might, may, must, cannot;
- "clitic": the clitics of contractions, 'll, 've, 'd, 't, 'm: "we'll", "don't";
- "adverb": adverbs between a subject and its verb, probably, never, always, please, not;
- "subj": subject nouns that take a verb next: speaker, court, person, user, people;
- "to": the infinitive marker "to";
- "code": module, package and namespace names that take a dot or method: fmt, os, np,
  fs, pd, assert, console, utils, org, com;
- "neg": a few words that sit before no verb (whether, either, cd, =, and, was, the):
  a small negative value.

Each class gets its mean activation on 8192 training rows. Other tokens get about 0.
The per-class values, not the word lists, carry the numbers; the lists are the concept.
"""

READS = ()

FIRST_SECOND = {"i", "we", "you", "me", "us"}
MODALS = {"will", "would", "should", "can", "could", "might", "may", "must", "cannot", "shall"}
CLITICS = {"ll", "ve", "d", "t", "m"}
ADVERBS = {"probably", "typically", "usually", "never", "always", "already", "often", "also",
           "just", "really", "still", "please", "definitely", "certainly", "not"}
SUBJECT_NOUNS = {"speaker", "court", "person", "user", "someone", "everyone", "people",
                 "researchers", "jury", "anyone", "police"}
CODE_NAMES = {"fmt", "os", "assert", "console", "math", "util", "utils", "np", "pd", "fs",
              "tf", "torch", "io", "self", "sys", "strings", "http", "path", "std", "bytes",
              "asyncio", "System", "Math", "StringUtils", "Utils", "await", "static", "org",
              "com", "apache", "google", "client", "api", "core", "unicode", "aws", "shutil"}
NEGATIVE = {"whether", "either", "unless", "however", "what", "name", "directory", "class",
            "cd", ".git", "run", "and", "was", "be", "but", "their", "is", "=", "the"}

# Mean activation of each class on training text.
VALUES = {"fp": 1.32, "modal": 0.76, "clitic": 1.44, "adverb": 0.38, "subj": 0.89,
          "to": 0.31, "code": 1.13, "neg": -0.11, "other": -0.01}


def word_class(token):
    """The class of one token, from its decoded text."""
    raw = token.strip()
    word = raw.lower().replace("’", "'")
    if word.startswith("'") and word[1:] in CLITICS:
        return "clitic"
    if word in FIRST_SECOND:
        return "fp"
    if word in MODALS:
        return "modal"
    if word in SUBJECT_NOUNS:
        return "subj"
    if word == "to":
        return "to"
    if word in ADVERBS:
        return "adverb"
    if raw in CODE_NAMES:
        return "code"
    if raw in NEGATIVE or word in NEGATIVE:
        return "neg"
    return "other"


def step(carry, prefix, upstream):
    """This component's activation at the newest token: its class's mean value."""
    return carry, VALUES[word_class(prefix.token_strings[-1])]
